template<class T> struct list_node { list_node *next; list_node *previous; T data; };
template<class T> class list {
    typedef list_node<T> node_type;
public:
    class iterator { friend class list<T>; node_type *node; public: iterator(node_type *value) : node(value) {} };
private:
    node_type *sentinel;
    node_type *create_node(const T &value) {
        const unsigned int bytes = (sizeof(node_type) + 7) & ~7;
        const unsigned int index = bytes / 8 - 1;
        allocator_object *raw = allocator_pool.free_list[index];
        void *memory;
        if (raw == 0) memory = allocator_refill(bytes);
        else { allocator_pool.free_list[index] = raw->next; memory = raw; }
        node_type *node = static_cast<node_type *>(memory);
        T *data = &node->data;
        if (data) new((void *)data) T(value);
        return node;
    }
    iterator insert(iterator position, const T &value) {
        node_type *node = create_node(value);
        node->next = position.node;
        node->previous = position.node->previous;
        position.node->previous->next = node;
        position.node->previous = node;
        return iterator(node);
    }
public:
    iterator end() { return iterator(sentinel); }
    void push_back(const T &value) { insert(end(), value); }
};

